key:
func displayName(_ name: String?) -> String {
    if let name, !name.isEmpty {
        return name
    }
    return "Гость"
}

if let достаёт String, а !name.isEmpty отдельно проверяет содержимое. nil и "" — разные случаи, но экрану здесь подходит одна замена.

