struct User { let name: String? }

func title(for user: User) -> String {
    return user.name!
}

key:
При User(name: nil) user.name! принудительно разворачивает nil — крэш.

func title(for user: User) -> String {
    user.name ?? "Гость"
}

При name == "" вернётся пустая строка: ?? её не заменяет. Если нужно — проверка isEmpty, как в ступени 2.

