func cardTitle(for user: User) -> String {
    // твой код
}

// nil    → "Гость · 0"
// "Нора" → "Нора · 4"
// ""     → "Гость · 0"

key:
func cardTitle(for user: User) -> String {
    let count: Int? = user.name?.count
    guard let name = user.name, !name.isEmpty else {
        return "Гость · 0"
    }
    return "\(name) · \(count ?? 0)"
}

user.name?.count — Int?: число, если имя есть, иначе nil. В реальном коде после guard проще взять name.count — chaining здесь для тренировки.

